const d = $input.first().json;
const trigger = $('Set - Normalize Input').first().json.trigger;

// Normalize features to 0-100 scale
const responseTimeScore = Math.max(0, Math.min(100,
  d.avg_response_time_minutes != null
    ? Math.max(0, 100 - (d.avg_response_time_minutes / 60) * 20)
    : 50  // unknown -> neutral
));

const absenceScore = Math.max(0, 100 - ((d.absence_rate || 0) * 100) * 2);
const lateScore = Math.max(0, 100 - ((d.late_rate || 0) * 100) * 1.5);
const noReplyScore = Math.max(0, 100 - (d.no_reply_count || 0) * 15);
const last30dScore = Math.min(100, (d.recent_mission_count || 0) * 10);

// Message clarity: how many reminders were needed
const remindersNeeded = [d.reminder_1_sent_at, d.reminder_2_sent_at, d.reminder_3_sent_at].filter(Boolean).length;
const clarityScore = Math.max(0, 100 - remindersNeeded * 25);

const features = {
  response_time_score: Math.round(responseTimeScore),
  absence_score: Math.round(absenceScore),
  late_score: Math.round(lateScore),
  no_reply_score: Math.round(noReplyScore),
  last30d_score: Math.round(last30dScore),
  clarity_score: Math.round(clarityScore),
  reminders_needed: remindersNeeded,
  current_status: d.current_status,
  trigger
};

return [{ json: { ...d, features } }];

