const aiResponse = $input.first().json;
const originalData = $('Code - Compute Features').first().json;

let parsed;
try {
  const content = aiResponse.choices?.[0]?.message?.content || '{}';
  parsed = JSON.parse(content);
} catch (e) {
  parsed = { risk_score: 75, risk_level: 'HIGH', main_risk_factors: ['Parse error'], recommended_actions: ['Manual review'], confidence: 0 };
}

return [{
  json: {
    ...originalData,
    risk_score: parsed.risk_score || 0,
    risk_level: parsed.risk_level || 'MEDIUM',
    main_risk_factors: parsed.main_risk_factors || [],
    recommended_actions: parsed.recommended_actions || [],
    ai_confidence: parsed.confidence || 0,
    is_high_risk: (parsed.risk_score || 0) >= 70
  }
}];

